/* Step 4: labels preserve the distinction between 5 mm/mV display height and standard-gain voltage. */
ECG_SVG['hypertrophy'].caption = 'A: LVH at half gain (5 mm/mV): convert displayed voltage to its 10 mm/mV equivalent before applying Sokolow–Lyon. B: representative low-voltage limb strip at full gain; diagnosis requires every limb lead. Low voltage with new alternans and tachycardia warrants immediate echo. Tap any zone.';
ECG_SVG['hypertrophy'].svg = ECG_SVG['hypertrophy'].svg
  .replace('½ gain 5 mm/mV', '½ gain: values ×2')
  .replace('>S 15</text>', '>S 7.5 → 15 mm</text>')
  .replace('>R 22</text>', '>R 11 → 22 mm</text>')
  .replace('SV1+RV5 = 37 mm ≥35 (half gain ×2)', 'SV1 + RV5 = 15 + 22 = 37 mm');

/* Step 4: keep measurement labels outside the tracings, as on a readable ECG printout. */
